package com.clara.workspace.application;
import java.nio.file.Path;import java.util.*;
public final class WorkspaceResumeRequest {private final String tenantId,userId,runId,interactionId,idempotencyKey;private final Path workspace;private final long expectedInstanceVersion;private final Map<String,Object> answer;
 public WorkspaceResumeRequest(String tenant,String user,String run,Path workspace,String interaction,long expected,String key,Map<String,Object> answer){if(blank(tenant)||blank(user)||blank(run)||workspace==null||!workspace.isAbsolute()||blank(interaction)||expected<0||blank(key))throw new IllegalArgumentException("workspace resume request is invalid");tenantId=tenant;userId=user;runId=run;this.workspace=workspace.normalize();interactionId=interaction;expectedInstanceVersion=expected;idempotencyKey=key;this.answer=answer==null?Collections.<String,Object>emptyMap():Collections.unmodifiableMap(new LinkedHashMap<String,Object>(answer));}
 public String getTenantId(){return tenantId;}public String getUserId(){return userId;}public String getRunId(){return runId;}public Path getWorkspace(){return workspace;}public String getInteractionId(){return interactionId;}public long getExpectedInstanceVersion(){return expectedInstanceVersion;}public String getIdempotencyKey(){return idempotencyKey;}public Map<String,Object> getAnswer(){return answer;}private static boolean blank(String v){return v==null||v.trim().isEmpty();}}
